INSERT INTO "snapshots" VALUES('efa42dbe-0306-452d-8fbe-f7a7dfc6f99e','2026-10-06T17:37:12.873518+00:00','{"attributes": {"_summarization": {"__class__": "nooa.interactive.SummarizationConfig", "__type__": "pydantic", "data": {"max_tokens": null, "policy": "token_budget", "preserve_recent": 10, "target_chars": 4000, "threshold_fraction": 0.75}}, "todo": {"__class__": "nooa.tools.todo.TodoManager", "__type__": "dict_class", "data": {"_active_id": null, "_order": [], "_todos": {}}}, "vars": {"__class__": "nooa.storage.snapshot_vars.SnapshotVars", "__type__": "dict_class", "data": {"_data": {}}}}, "context": [{"expr": "self.queue_manager.status()", "key": "queues", "type": "dynamic"}, {"expr": "self.skills.status()", "key": "skills", "type": "dynamic"}, {"expr": "self.todo.status()", "key": "todo_status", "type": "dynamic"}, {"key": "python_cell_tools", "type": "static", "value": "class RepoTools:\n    \"\"\"Find code locations as ShellTools ``Match`` anchors.\"\"\"\n\n    source_dir: Path | None  # Directory containing this skill''s source code, or None if unknown.\n\n    async def symbols(self, path: str = ''.'', query: str = '''', max_results: int = 50, cwd: str | Path | None = None) -> RepoResult:\n        \"\"\"Find definitions under a file or directory; ``cwd`` defaults to the shell''s current directory.\"\"\"\n    async def refs(self, name: str, path: str = ''.'', max_results: int = 50, cwd: str | Path | None = None) -> RepoResult:\n        \"\"\"Find references/usages of a symbol, excluding definitions.\"\"\"\nclass ActivityShellTools:\n    \"\"\"A composed ``ShellTools`` substitute that emits transient activity events.\"\"\"\n\n    source_dir: Path | None  # Directory containing this skill''s source code, or None if unknown.\n\n    async def run(self, command: str, *, stdin: str | None = None, timeout: float = 30.0, cwd: str | Path | None = None) -> ShellResult:\n        \"\"\"Run a shell command in the persistent session (cd/env/cwd survive).\"\"\"\n    def run_stream(self, command: str, *, stdin: str | None = None, timeout: float = 30.0, cwd: str | Path | None = None) -> AsyncIterator[StreamEvent | StreamDone]:\n        \"\"\"Stream command output line-by-line as it arrives, ending with a done event.\"\"\"\n    async def read(self, path: str, lines: tuple[int, int] | None = None) -> Match:\n        \"\"\"Read a file (or line range) -> Match object.\"\"\"\n    async def replace(self, target: Any, old_or_new: str = '''', new: str | None = None) -> FileWrite:\n        \"\"\"Edit a file \u2014 two forms:\"\"\"\n    async def write_file(self, path: str, content: str) -> FileWrite:\n        \"\"\"Create or overwrite a file with content (no shell quoting needed).\"\"\"\nclass TodoManager:\n    \"\"\"Track multi-step work, dependencies, metadata, and progress comments.\"\"\"\n\n    source_dir: Path | None  # Directory containing this skill''s source code, or None if unknown.\n\n    def add(self, title: str, deps: list[Todo | str] | None = None, description: str = '''', **vars: Any) -> Todo:\n        \"\"\"Create and return an open todo.\"\"\"\n    def get(self, todo_id: Todo | str) -> Todo | None:\n        \"\"\"Return the matching managed todo, or ``None`` if it is missing.\"\"\"\n    def complete(self, todo_id: Todo | str) -> Todo | None:\n        \"\"\"Mark a todo done and return it, or ``None`` if it is missing.\"\"\"\n    def update(self, todo_id: Todo | str, **kwargs: Any) -> Todo | None:\n        \"\"\"Update ``title``, ``status``, or ``description`` and return the todo.\"\"\"\n    def activate(self, todo_id: Todo | str) -> Todo:\n        \"\"\"Make one open todo the active task shown prominently by ``status()``.\"\"\"\n    def set_var(self, todo_id: Todo | str, key: str, value: Any) -> Todo | None:\n        \"\"\"Store durable metadata and return the todo, or ``None`` if it is missing.\"\"\"\n    def get_var(self, todo_id: Todo | str, key: str) -> Any | None:\n        \"\"\"Return a metadata value, or ``None`` if the todo or key is missing.\"\"\"\n    def comment(self, todo_id: Todo | str, body: str) -> TodoComment | None:\n        \"\"\"Append material progress and return it, or ``None`` if missing.\"\"\"\n    def comments(self, todo_id: Todo | str) -> list[TodoComment]:\n        \"\"\"Return a chronological copy of comments, or ``[]`` if none exist.\"\"\"\n    def list_todos(self, status: str | None = None) -> list[Todo]:\n        \"\"\"Return todos in creation order, optionally filtered by effective status.\"\"\"\n    def status(self, max_items: int = 10, max_chars: int = 2000) -> str:\n        \"\"\"Return a compact, bounded progress summary.\"\"\"\n\n## Referenced Types\nclass RepoResult(BaseModel):\n    \"\"\"Repository symbol/reference matches and their display metadata.\"\"\"\n\n    query: str  # Search query or symbol name\n    lines: list[str]  # Display lines: file:line: context\n    matches: list[Match]  # Match anchors; pass one to self.shell.replace() to edit it\n    total_matches: int = 0  # Total matches found\n    truncated: bool = False  # True if results were capped\n    diagnostic: PathResolutionError | None = None  # Structured path failure, including resolved path and base\nclass FileWrite:\n    \"\"\"Result of a write/replace operation.\"\"\"\n\n    path: path\n    message: message\n    diff: diff\n    new_text: new_text\nclass Match:\n    \"\"\"Editable file anchor returned by file/search tools.\"\"\"\n\n    path: str  # File path.\n    resolved_path: str  # Canonical file path captured when this match was created.\n    start: int  # First line number (1-indexed).\n    end: int  # Last line number (1-indexed, inclusive).\n    text: str  # Raw file content (no line numbers).\n    numbered: str  # Content with line-number gutter.\nclass ShellResult:\n    \"\"\"Result of run() \u2014 a str subclass whose VALUE is stdout.\"\"\"\n\n    stdout: str\n    stderr: str\n    returncode: int\n    timed_out: bool\n    success: bool\n    matches: list[Match] | None\n    text: str  # The structured display text (i.e. ``str(self)``).\n@dataclass\nclass StreamDone:\n    kind: Literal[done]  # Terminal stream event kind\n    returncode: int  # Final process exit code\n    timed_out: bool  # True if command exceeded timeout\n@dataclass\nclass StreamEvent:\n    kind: Literal[stdout, stderr]  # Stream chunk event kind\n    text: str  # Chunk text for the stream event\nclass Todo(BaseModel):\n    \"\"\"A managed task; blocking is derived from unfinished dependencies.\"\"\"\n\n    id: str  # Stable task ID\n    title: str = ''''  # Short action-oriented description\n    status: Literal[open, done] = ''open''  # Stored status; blocking is derived from dependencies\n    deps: list[str]  # IDs of prerequisite todos\n    created_at: str  # Creation time\n    description: str = ''''  # Current scope, constraints, approach, and definition of done\n    comments: list[TodoComment]  # Append-only chronological progress journal\nclass TodoComment(BaseModel):\n    \"\"\"An append-only, snapshot-backed progress-journal entry.\"\"\"\n\n    id: str\n    body: str\n    created_at: str"}, {"expr": "self._coding_state_context()", "key": "coding_state", "type": "dynamic"}, {"expr": "self.context_stats.format() if self.context_stats else ''''", "key": "context_usage", "type": "dynamic"}], "disabled_context": [], "type_allowlist": ["nooa.interactive.SummarizationConfig", "nooa.storage.snapshot_vars.SnapshotVars", "nooa.tools.todo.TodoManager"], "version": 2}');
